// Writes the output of f, padded according to format specifications in specs.
// size: output size in code units.
// width: output display width in (terminal) column positions.
template <align::type align = align::left, typename OutputIt, typename Char,
          typename F>
FMT_CONSTEXPR OutputIt write_padded(OutputIt out,
                                    const basic_format_specs<Char>& specs,
                                    size_t size, size_t width, F&& f) {
  static_assert(align == align::left || align == align::right, "");
  specs_setter<Char> setter(const_cast<basic_format_specs<Char>&>(specs));
  setter.capture_output_geometry(to_unsigned(specs.width),
                                 static_cast<unsigned>(specs.align), size,
                                 width);
  setter.padding_shift_index(static_cast<unsigned>(specs.align));
  setter.fill_unit_size(specs.fill.size());
  setter.fill_repeat_count(setter.total_padding(), specs.fill.size());
  auto* shifts = align == align::left ? data::left_padding_shifts
                                      : data::right_padding_shifts;
  size_t left_padding = setter.count_left_padding(shifts);
  size_t right_padding = setter.count_right_padding(shifts);
  auto it = reserve(out, setter.padded_output_size(specs.fill.size()));
  if (left_padding != 0) it = fill(it, left_padding, specs.fill);
  it = f(it);
  if (right_padding != 0) it = fill(it, right_padding, specs.fill);
  return base_iterator(out, it);
}

